import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { useAppDispatch, useAppSelector } from '../hooks/useAppDispatch';
import { loginStart, loginSuccess, loginFailure } from '../store/authSlice';
import { authApi } from '../services/api';

export const Login: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const { user, loading, error } = useAppSelector(s => s.auth);

  const [userId, setUserId] = useState('');
  const [pin, setPin] = useState(['', '', '', '']);
  const pinRefs = [
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
  ];

  useEffect(() => {
    if (user) {
      if (user.role === 'TDR') navigate('/tdr', { replace: true });
      if (user.role === 'ZBM') navigate('/zbm', { replace: true });
      if (user.role === 'HSD') navigate('/hsd', { replace: true });
    }
  }, [user, navigate]);

  const handlePinChange = (index: number, value: string) => {
    if (!/^\d?$/.test(value)) return;
    const newPin = [...pin];
    newPin[index] = value;
    setPin(newPin);
    if (value && index < 3) pinRefs[index + 1].current?.focus();
  };

  const handlePinKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace' && !pin[index] && index > 0) {
      pinRefs[index - 1].current?.focus();
    }
    if (e.key === 'Enter') handleSubmit();
  };

  const handleSubmit = async () => {
    const pinStr = pin.join('');
    if (!userId.trim()) { toast.error('Please enter your User ID'); return; }
    if (pinStr.length !== 4) { toast.error('Please enter your 4-digit PIN'); return; }
    dispatch(loginStart());
    try {
      const res = await authApi.login(userId.trim(), pinStr);
      dispatch(loginSuccess(res.data));
      const role = res.data.user.role;
      if (role === 'TDR') navigate('/tdr');
      if (role === 'ZBM') navigate('/zbm');
      if (role === 'HSD') navigate('/hsd');
    } catch (err: unknown) {
      const message = (err as { response?: { data?: { error?: string } } })?.response?.data?.error || 'Login failed. Check your ID and PIN.';
      dispatch(loginFailure(message));
      toast.error(message);
      setPin(['', '', '', '']);
      pinRefs[0].current?.focus();
    }
  };

  return (
    <div className="min-h-screen flex flex-col" style={{ background: 'linear-gradient(135deg, #00843D 0%, #006B31 50%, #004d24 100%)' }}>

      {/* Top wave decoration */}
      <div className="absolute top-0 left-0 right-0 h-48 overflow-hidden pointer-events-none">
        <svg viewBox="0 0 1440 200" className="w-full" preserveAspectRatio="none">
          <path d="M0,100 C360,180 1080,20 1440,100 L1440,0 L0,0 Z" fill="rgba(255,255,255,0.08)" />
          <path d="M0,140 C480,60 960,200 1440,120 L1440,0 L0,0 Z" fill="rgba(228,0,124,0.15)" />
        </svg>
      </div>

      {/* Main content */}
      <div className="flex-1 flex flex-col items-center justify-center px-4 py-8 relative z-10">

        {/* Logo + Title */}
        <div className="mb-8 text-center">
          {/* Zamtel logo mark */}
          <div className="inline-flex items-center justify-center w-24 h-24 rounded-3xl shadow-2xl mb-5"
               style={{ background: 'linear-gradient(135deg, #E4007C, #ff3399)' }}>
            <svg viewBox="0 0 80 80" className="w-14 h-14" fill="none">
              <text x="8" y="56" fontFamily="Arial Black, sans-serif" fontWeight="900"
                    fontSize="52" fill="white">Z</text>
            </svg>
          </div>
          <h1 className="text-white text-3xl font-black tracking-tight drop-shadow">
            Zamtel
          </h1>
          <p className="text-white/80 text-base font-medium mt-1">TDR Monitor</p>
          <div className="flex items-center justify-center gap-2 mt-2">
            <div className="w-8 h-0.5 bg-white/30 rounded" />
            <p className="text-white/60 text-xs">Territory Development Representative</p>
            <div className="w-8 h-0.5 bg-white/30 rounded" />
          </div>
        </div>

        {/* Login Card */}
        <div className="bg-white rounded-3xl shadow-2xl p-7 w-full max-w-sm">

          {/* Card header */}
          <div className="flex items-center gap-3 mb-6">
            <div className="w-1 h-7 rounded-full" style={{ background: 'linear-gradient(to bottom, #E4007C, #00843D)' }} />
            <h2 className="text-xl font-black text-gray-800">Sign In</h2>
          </div>

          {/* User ID */}
          <div className="mb-5">
            <label className="block text-sm font-semibold text-gray-600 mb-2">User ID</label>
            <input
              type="text"
              placeholder="e.g. hsd-001 / zbm-cb-01 / tdr-cb-01"
              value={userId}
              onChange={e => setUserId(e.target.value)}
              autoComplete="username"
              autoFocus
              className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:outline-none focus:border-green-600 text-gray-800 text-sm font-medium transition bg-gray-50"
              style={{ '--tw-ring-color': '#00843D' } as React.CSSProperties}
            />
          </div>

          {/* PIN boxes */}
          <div className="mb-6">
            <label className="block text-sm font-semibold text-gray-600 mb-3">4-Digit PIN</label>
            <div className="flex gap-3 justify-center">
              {pin.map((digit, i) => (
                <input
                  key={i}
                  ref={pinRefs[i]}
                  type="password"
                  inputMode="numeric"
                  pattern="\d*"
                  maxLength={1}
                  value={digit}
                  onChange={e => handlePinChange(i, e.target.value)}
                  onKeyDown={e => handlePinKeyDown(i, e)}
                  className="w-14 h-14 text-center text-2xl font-black border-2 rounded-2xl focus:outline-none transition"
                  style={{
                    borderColor: digit ? '#E4007C' : '#e5e7eb',
                    backgroundColor: digit ? '#fff0f8' : '#f9fafb',
                    color: '#1a1a1a',
                  }}
                />
              ))}
            </div>
          </div>

          {/* Error */}
          {error && (
            <div className="mb-4 px-4 py-3 rounded-xl bg-red-50 border border-red-200">
              <p className="text-sm text-red-600 text-center font-medium">{error}</p>
            </div>
          )}

          {/* Submit button */}
          <button
            onClick={handleSubmit}
            disabled={loading}
            className="w-full py-4 rounded-2xl text-white font-black text-base shadow-lg transition active:scale-95 disabled:opacity-70"
            style={{ background: loading ? '#9CA3AF' : 'linear-gradient(135deg, #00843D, #006B31)' }}
          >
            {loading ? (
              <span className="flex items-center justify-center gap-2">
                <svg className="animate-spin w-5 h-5" viewBox="0 0 24 24" fill="none">
                  <circle cx="12" cy="12" r="10" stroke="white" strokeWidth="3" strokeDasharray="30 70" />
                </svg>
                Signing in...
              </span>
            ) : 'Sign In →'}
          </button>

          {/* Pink accent divider */}
          <div className="flex items-center gap-3 my-5">
            <div className="flex-1 h-px bg-gray-100" />
            <div className="w-2 h-2 rounded-full" style={{ backgroundColor: '#E4007C' }} />
            <div className="flex-1 h-px bg-gray-100" />
          </div>

          <p className="text-xs text-gray-400 text-center font-medium">
            Zambia Telecommunications Company Ltd
          </p>
        </div>

        {/* Bottom hint */}
        <p className="text-white/50 text-xs mt-6 text-center">
          Powered by Zamgrow Technology Platform
        </p>
      </div>

      {/* Bottom wave */}
      <div className="absolute bottom-0 left-0 right-0 h-32 overflow-hidden pointer-events-none">
        <svg viewBox="0 0 1440 130" className="w-full" preserveAspectRatio="none">
          <path d="M0,60 C360,120 1080,0 1440,80 L1440,130 L0,130 Z" fill="rgba(228,0,124,0.12)" />
          <path d="M0,90 C480,30 960,130 1440,60 L1440,130 L0,130 Z" fill="rgba(255,255,255,0.06)" />
        </svg>
      </div>
    </div>
  );
};
